package main

import "unsafe"

// CHECK: {{^}}@[[GLOB1:[0-9]+]] = private unnamed_addr constant [14 x i8] c"error type f32", align 1{{$}}
// CHECK: {{^}}@[[GLOB3:[0-9]+]] = private unnamed_addr constant [14 x i8] c"error bits f32", align 1{{$}}
// CHECK: {{^}}@[[GLOB5:[0-9]+]] = private unnamed_addr constant [14 x i8] c"error type f64", align 1{{$}}
// CHECK: {{^}}@[[GLOB6:[0-9]+]] = private unnamed_addr constant [14 x i8] c"error bits f64", align 1{{$}}

const pi = 3.14159265
const pi32bits = 0x40490fdb
const pi64lo = 0x53c8d4f1
const pi64hi = 0x400921fb

type eface struct {
	typ  unsafe.Pointer
	data unsafe.Pointer
}

type u64parts struct {
	lo uint32
	hi uint32
}

// check32 must test the dynamic type and then inspect the data pointer from the
// same interface value; the decimal constant is pi32bits.
func check32(v any) {
	switch v.(type) {
	case float32:
	default:
		panic("error type f32")
	}
	e := *(*eface)(unsafe.Pointer(&v))
	if *(*uint32)(e.data) != pi32bits {
		panic("error bits f32")
	}
}

func check64(v any) {
	switch v.(type) {
	case float64:
	default:
		panic("error type f64")
	}
	e := *(*eface)(unsafe.Pointer(&v))
	bits := *(*u64parts)(e.data)
	if bits.lo != pi64lo || bits.hi != pi64hi {
		panic("error bits f64")
	}
}

func f32() float32 {
	return pi
}

func f64() float64 {
	return pi
}

func main() {
	check32(f32())
	check64(f64())
}

